'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { computeSummary, welchTest } = require('../lib/stats');
const { parseArgs } = require('../lib/collect');

test('computeSummary: 单样本', () => {
  const s = computeSummary([100]);
  assert.deepEqual(s, {
    count: 1,
    min: 100,
    max: 100,
    mean: 100,
    median: 100,
    p95: 100,
    stddev: 0,
  });
});

test('computeSummary: 偶数样本 median 取中间两值平均', () => {
  // 10, 20, 30, 40
  const s = computeSummary([40, 10, 30, 20]);
  assert.equal(s.count, 4);
  assert.equal(s.min, 10);
  assert.equal(s.max, 40);
  assert.equal(s.mean, 25);
  assert.equal(s.median, 25);
  // ceil(0.95*4) = ceil(3.8) = 4 项
  assert.equal(s.p95, 40);
  // 总体标准差: sqrt(((225+25+25+225))/4) = sqrt(125)
  assert.equal(s.stddev, Math.round(Math.sqrt(125) * 1e6) / 1e6);
});

test('computeSummary: p95 取 ceil(0.95*count) 项', () => {
  const values = Array.from({ length: 20 }, (_, i) => (i + 1) * 10);
  const s = computeSummary(values);
  // ceil(0.95*20) = 19 -> 第 19 项 = 190
  assert.equal(s.p95, 190);
  assert.equal(s.median, 105); // (100+110)/2
});

test('computeSummary: 21 个样本 p95 与奇数 median', () => {
  const values = Array.from({ length: 21 }, (_, i) => (i + 1) * 10);
  const s = computeSummary(values);
  // ceil(0.95*21) = ceil(19.95) = 20 -> 200
  assert.equal(s.p95, 200);
  assert.equal(s.median, 110);
});

test('computeSummary: 浮点保留六位小数', () => {
  // 1,2 -> mean 1.5, 总体标准差 0.5
  const s = computeSummary([1, 2]);
  assert.equal(s.mean, 1.5);
  assert.equal(s.stddev, 0.5);
  for (const key of ['mean', 'median', 'stddev']) {
    const decimals = String(s[key]).split('.')[1] || '';
    assert.ok(decimals.length <= 6);
  }
});

test('welchTest: 已知取值（t=3.674235, df=4, 双侧 p=0.021312）', () => {
  const w = welchTest([1, 2, 3], [4, 5, 6]);
  assert.deepEqual(w, { t_statistic: 3.674235, degrees_of_freedom: 4, p_value: 0.021312 });
});

test('welchTest: 零方差相同均值 -> {0, null, 1}', () => {
  assert.deepEqual(welchTest([5, 5, 5], [5, 5]),
    { t_statistic: 0, degrees_of_freedom: null, p_value: 1 });
});

test('welchTest: 零方差不同均值 -> {null, null, 0}', () => {
  assert.deepEqual(welchTest([5, 5], [7, 7, 7]),
    { t_statistic: null, degrees_of_freedom: null, p_value: 0 });
});

test('welchTest: 单侧零方差仍可计算', () => {
  const w = welchTest([100, 100, 100], [100, 110, 120]);
  assert.equal(typeof w.t_statistic, 'number');
  assert.equal(typeof w.degrees_of_freedom, 'number');
  assert.ok(w.p_value > 0 && w.p_value < 1);
});

test('parseArgs: --key=value 与 --key value 混用', () => {
  const { values, error } = parseArgs(['--runs=3', '--command', 'true']);
  assert.equal(error, null);
  assert.equal(values.runs, '3');
  assert.equal(values.command, 'true');
});

test('parseArgs: 无法解析的位置参数', () => {
  const { error } = parseArgs(['collect']);
  assert.match(error, /无法解析/);
});

test('parseArgs: 未知参数', () => {
  const { error } = parseArgs(['--bogus', '1']);
  assert.match(error, /未知参数/);
});

test('parseArgs: 缺少取值', () => {
  const { error } = parseArgs(['--runs']);
  assert.match(error, /缺少取值/);
});

test('parseArgs: 重复参数', () => {
  const { error } = parseArgs(['--runs', '1', '--runs', '2']);
  assert.match(error, /重复/);
});

{
  "name": "perf-regress",
  "version": "0.1.0",
  "description": "性能基准与回归检测服务：基准采集、统计显著性与回归归因",
  "private": true,
  "bin": {
    "perf-regress": "bin/perf-regress.js"
  },
  "scripts": {
    "test": "node --test"
  },
  "license": "MIT"
}

#!/usr/bin/env node
'use strict';

const { collect, EXIT_USAGE } = require('../lib/collect');
const { collectSuite } = require('../lib/collect-suite');
const { compare } = require('../lib/compare');
const { compareSuite } = require('../lib/compare-suite');
const { compareSeries } = require('../lib/compare-series');
const { ab } = require('../lib/ab');
const { abSuite } = require('../lib/ab-suite');

const USAGE = `Usage: perf-regress collect --command <cmd> --runs <n> --warmup <n> \
--timeout-ms <ms> --output <path>
       perf-regress collect-suite --manifest <path> --output <path>
       perf-regress compare --baseline <path> --candidate <path> --output <path> \
[--alpha <a>] [--min-change-percent <p>]
       perf-regress compare-suite --manifest <path> --output <path> \
[--alpha <a>] [--min-change-percent <p>]
       perf-regress compare-series --manifest <path> --output <path> \
[--alpha <a>] [--min-change-percent <p>]
       perf-regress ab --baseline-command <cmd> --candidate-command <cmd> \
--runs <n> --warmup <n> --timeout-ms <ms> --output <path> \
[--alpha <a>] [--min-change-percent <p>]
       perf-regress ab-suite --manifest <path> --output <path> \
[--alpha <a>] [--min-change-percent <p>]

collect：顺序执行目标命令进行基准采集，结果以 UTF-8 JSON 写入 --output。
collect-suite：按 manifest 顺序批量采集多个基准场景，含逐 case 结果与套件汇总。
compare：比较两份 collect JSON，输出显著性、回归判定与变化归因。
compare-suite：按 manifest 批量比较多对 collect JSON，含 BH 校正与套件级汇总。
compare-series：定位每个 case 的候选序列相对固定 baseline 的回归起点，
    全部候选统一 BH 校正，含套件级汇总与归因。
ab：基线与候选同批交替测量（先全部预热再测量，每轮先 baseline 后 candidate），
    输出两侧采集结果与即时比较。
ab-suite：按 manifest 串行执行多个交错 A/B 场景，含 BH 校正、套件汇总与归因。

collect 选项：
  --command <cmd>     被测命令（通过 /bin/sh -c 执行），必填
  --runs <n>          计入统计的执行次数，>= 1，必填
  --warmup <n>        预热次数，>= 0，缺省 0
  --timeout-ms <ms>   单次执行超时（毫秒），>= 1，必填
  --output <path>     唯一 JSON 输出文件，必填

collect-suite 选项：
  --manifest <path>   套件 manifest JSON（UTF-8，含非空 cases），必填
  --output <path>     套件采集结果 JSON 输出文件，必填

compare 选项：
  --baseline <path>            基线 collect JSON，必填
  --candidate <path>           候选 collect JSON，必填
  --output <path>              比较结果 JSON 输出文件，必填
  --alpha <a>                  显著性水平，0 < a < 1，缺省 0.05
  --min-change-percent <p>     回归/改进判定阈值（百分比），>= 0，缺省 5

compare-suite 选项：
  --manifest <path>            套件 manifest JSON（含非空 cases），必填
  --output <path>              套件比较结果 JSON 输出文件，必填
  --alpha <a>                  显著性水平，0 < a < 1，缺省 0.05
  --min-change-percent <p>     回归/改进判定阈值（百分比），>= 0，缺省 5

compare-series 选项：
  --manifest <path>            系列 manifest JSON（含非空 cases），必填
  --output <path>              系列比较结果 JSON 输出文件，必填
  --alpha <a>                  显著性水平，0 < a < 1，缺省 0.05
  --min-change-percent <p>     回归/改进判定阈值（百分比），>= 0，缺省 5

ab 选项：
  --baseline-command <cmd>     基线命令（通过 /bin/sh -c 执行），必填
  --candidate-command <cmd>    候选命令（通过 /bin/sh -c 执行），必填
  --runs <n>                   每侧计入统计的执行次数，>= 2，必填
  --warmup <n>                 每侧预热次数，>= 0，缺省 0
  --timeout-ms <ms>            单次执行超时（毫秒），>= 1，必填
  --output <path>              唯一 JSON 输出文件，必填
  --alpha <a>                  显著性水平，0 < a < 1，缺省 0.05
  --min-change-percent <p>     回归/改进判定阈值（百分比），>= 0，缺省 5

ab-suite 选项：
  --manifest <path>            套件 manifest JSON（含非空 cases），必填
  --output <path>              套件结果 JSON 输出文件，必填
  --alpha <a>                  显著性水平，0 < a < 1，缺省 0.05
  --min-change-percent <p>     回归/改进判定阈值（百分比），>= 0，缺省 5

退出码：
  0  成功
  2  参数错误或输入无效（collect/collect-suite/ab/ab-suite 含进程无法启动；不创建或改写 output）
  3  collect/collect-suite：measure 阶段存在被跳过的异常（仍写 output）；
     ab/ab-suite：存在 measure 错误或任一侧有效样本少于 2（仍写 output）
  4  output 写入失败
`;

async function main() {
  const [subcommand, ...rest] = process.argv.slice(2);

  if (subcommand === undefined || subcommand === '-h' || subcommand === '--help') {
    process.stdout.write(USAGE);
    process.exit(0);
  }

  if (subcommand !== 'collect' && subcommand !== 'collect-suite'
    && subcommand !== 'compare'
    && subcommand !== 'compare-suite'
    && subcommand !== 'compare-series'
    && subcommand !== 'ab'
    && subcommand !== 'ab-suite') {
    process.stderr.write(`perf-regress: 未知子命令: ${subcommand}\n\n${USAGE}`);
    process.exit(EXIT_USAGE);
  }

  if (rest.includes('-h') || rest.includes('--help')) {
    process.stdout.write(USAGE);
    process.exit(0);
  }

  const code = subcommand === 'collect' ? await collect(rest)
    : subcommand === 'collect-suite' ? await collectSuite(rest)
      : subcommand === 'compare' ? await compare(rest)
        : subcommand === 'compare-suite' ? await compareSuite(rest)
          : subcommand === 'compare-series' ? await compareSeries(rest)
            : subcommand === 'ab' ? await ab(rest)
              : await abSuite(rest);
  process.exit(code);
}

main().catch((err) => {
  process.stderr.write(`perf-regress: 未预期错误: ${err.stack || err.message}\n`);
  process.exit(1);
});

