const LANCZOS = [0.99999999999980993,676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
function logGamma(z){if(z<0.5){return Math.log(Math.PI/Math.sin(Math.PI*z))-logGamma(1-z);}const w=z-1;let x=LANCZOS[0];for(let i=1;i<LANCZOS.length;i++){x+=LANCZOS[i]/(w+i);}const t=w+7.5;return 0.5*Math.log(2*Math.PI)+(w+0.5)*Math.log(t)-t+Math.log(x);}
function betacf(a,b,x){const MAX=200,EPS=3e-14,FPMIN=1e-300;const qab=a+b,qap=a+1,qam=a-1;let c=1;let d=1-(qab*x)/qap;if(Math.abs(d)<FPMIN)d=FPMIN;d=1/d;let h=d;for(let m=1;m<=MAX;m++){const m2=2*m;let aa=(m*(b-m)*x)/((qam+m2)*(a+m2));d=1+aa*d;if(Math.abs(d)<FPMIN)d=FPMIN;c=1+aa/c;if(Math.abs(c)<FPMIN)c=FPMIN;d=1/d;h*=d*c;aa=(-(a+m)*(qab+m)*x)/((a+m2)*(qap+m2));d=1+aa*d;if(Math.abs(d)<FPMIN)d=FPMIN;c=1+aa/c;if(Math.abs(c)<FPMIN)c=FPMIN;d=1/d;const del=d*c;h*=del;if(Math.abs(del-1)<EPS)break;}return h;}
function rib(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const lf=a*Math.log(x)+b*Math.log(1-x)+logGamma(a+b)-logGamma(a)-logGamma(b);const f=Math.exp(lf);if(x<(a+1)/(a+b+2))return (f*betacf(a,b,x))/a;return 1-(f*betacf(b,a,1-x))/b;}
function twoTail(df,t){return rib(df/(df+t*t),df/2,0.5);}
function tcrit(df,p){let lo=0,hi=1;while(twoTail(df,hi)>p)hi*=2;for(let i=0;i<200;i++){const mid=(lo+hi)/2;if(twoTail(df,mid)>p)lo=mid;else hi=mid;}return (lo+hi)/2;}
