console.log("df2",r6(tcrit(2,0.05)),"exp 4.302653");
console.log("df1000",r6(tcrit(1000,0.05)),"exp 1.962339");
console.log("df4 alpha.1",r6(tcrit(4,0.1)),"exp 2.131847");
console.log("df4 alpha.01",r6(tcrit(4,0.01)),"exp 4.604095");
